package org.novasos.healthysv2.appointment;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.novasos.healthysv2.TestcontainersConfiguration;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.*;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.context.annotation.*;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.oauth2.jwt.*;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;
@ActiveProfiles("test") @SpringBootTest(properties={"spring.security.oauth2.resourceserver.jwt.issuer-uri=https://keycloak.example/realms/healthys","spring.security.oauth2.resourceserver.jwt.audiences=healthys-backend-apps","healthys.security.api-client-id=healthys-backend-apps","healthys.security.cors.allowed-origins=http://localhost:5173"}) @AutoConfigureMockMvc @Import({TestcontainersConfiguration.class,AppointmentApiIntegrationTests.JwtFixtures.class}) @Transactional
class AppointmentApiIntegrationTests{
 static final UUID ADMIN=UUID.fromString("40000000-0000-0000-0000-000000000001"),DOCTOR_KEYCLOAK=UUID.fromString("40000000-0000-0000-0000-000000000002"),PATIENT_KEYCLOAK=UUID.fromString("40000000-0000-0000-0000-000000000003");@Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;
 @Test void managesAppointmentParticipantsHistoryAndQueue()throws Exception{Graph g=graph();Instant start=Instant.now().plusSeconds(7200);UUID appointment=create(g,start,start.plusSeconds(1800));mvc.perform(post("/api/v1/appointments/{id}/participants",appointment).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"personId\":\"%s\",\"role\":\"COMPANION\"}".formatted(g.participant))).andExpect(status().isCreated());Instant moved=start.plusSeconds(3600);mvc.perform(post("/api/v1/appointments/{id}/reschedule",appointment).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"scheduledStart\":\"%s\",\"scheduledEnd\":\"%s\",\"reason\":\"Doctor request\"}".formatted(moved,moved.plusSeconds(1800)))).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("RESCHEDULED"));mvc.perform(post("/api/v1/appointments/{id}/status",appointment).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"CONFIRMED\"}")).andExpect(status().isOk());String queue=mvc.perform(post("/api/v1/appointments/{id}/queue/check-in",appointment).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isCreated()).andExpect(jsonPath("$.status").value("WAITING")).andReturn().getResponse().getContentAsString();UUID queueId=id(queue);mvc.perform(post("/api/v1/appointments/{a}/queue/{q}/call",appointment,queueId).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("CALLED"));mvc.perform(post("/api/v1/appointments/{a}/queue/{q}/complete",appointment,queueId).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("COMPLETED"));mvc.perform(get("/api/v1/appointments/{id}",appointment).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isOk()).andExpect(jsonPath("$.participants.length()").value(1)).andExpect(jsonPath("$.history.length()").value(4)).andExpect(jsonPath("$.queue.length()").value(1));}
 @Test void rejectsOverlappingOrUnavailableSlot()throws Exception{Graph g=graph();Instant start=Instant.now().plusSeconds(7200);create(g,start,start.plusSeconds(1800));mvc.perform(post("/api/v1/appointments").header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content(body(g,start.plusSeconds(300),start.plusSeconds(1200)))).andExpect(status().isUnprocessableContent()).andExpect(jsonPath("$.code").value("PROFESSIONAL_UNAVAILABLE"));mvc.perform(get("/api/v1/appointments/availability").header(HttpHeaders.AUTHORIZATION,"Bearer admin").param("professionalId",g.professional.toString()).param("organizationId",g.organization.toString()).param("start",start.plusSeconds(300).toString()).param("end",start.plusSeconds(1200).toString())).andExpect(status().isOk()).andExpect(jsonPath("$.available").value(false));}
 @Test void cancelsAppointmentAndBuildsDoctorAndPatientAgendas()throws Exception{Graph g=graph();Instant start=Instant.now().plusSeconds(7200);UUID appointment=create(g,start,start.plusSeconds(1800));mvc.perform(get("/api/v1/appointments/me").header(HttpHeaders.AUTHORIZATION,"Bearer doctor")).andExpect(status().isOk()).andExpect(jsonPath("$.content.length()").value(1));mvc.perform(get("/api/v1/appointments/me").header(HttpHeaders.AUTHORIZATION,"Bearer patient")).andExpect(status().isOk()).andExpect(jsonPath("$.content.length()").value(1));mvc.perform(post("/api/v1/appointments/{id}/cancel",appointment).header(HttpHeaders.AUTHORIZATION,"Bearer patient").contentType(MediaType.APPLICATION_JSON).content("{\"reason\":\"Unavailable\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("CANCELLED")).andExpect(jsonPath("$.history[-1:].newStatus").value("CANCELLED"));}
 private UUID create(Graph g,Instant start,Instant end)throws Exception{return id(mvc.perform(post("/api/v1/appointments").header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content(body(g,start,end))).andExpect(status().isCreated()).andExpect(jsonPath("$.appointmentNumber").exists()).andReturn().getResponse().getContentAsString());}private String body(Graph g,Instant start,Instant end){return "{\"patientId\":\"%s\",\"professionalId\":\"%s\",\"organizationId\":\"%s\",\"type\":\"CONSULTATION\",\"scheduledStart\":\"%s\",\"scheduledEnd\":\"%s\",\"reason\":\"Check-up\"}".formatted(g.patient,g.professional,g.organization,start,end);}private Graph graph(){UUID adminPerson=person(ADMIN),doctorPerson=person(DOCTOR_KEYCLOAK),patientPerson=person(PATIENT_KEYCLOAK),participant=person(null),organization=organization(),professional=professional(doctorPerson),patient=patient(patientPerson),assignment=UUID.randomUUID();jdbc.update("insert into professional.professional_assignment(id,professional_id,organization_id,start_date,status) values (?,?,?,?,?)",assignment,professional,organization,LocalDate.now(),"ACTIVE");jdbc.update("insert into professional.professional_availability(id,assignment_id,start_at,end_at,availability_type,status) values (?,?,?,?,?,?)",UUID.randomUUID(),assignment,java.sql.Timestamp.from(Instant.now()),java.sql.Timestamp.from(Instant.now().plus(Duration.ofDays(5))),"CONSULTATION","AVAILABLE");return new Graph(patient,professional,organization,participant);}private UUID person(UUID keycloak){UUID id=keycloak==ADMIN?UUID.randomUUID():UUID.randomUUID();jdbc.update("insert into identity.person(id,person_number,keycloak_user_id,first_name,last_name,status) values (?,?,?,?,?,?)",id,"PER-"+id,keycloak,"Test","User","ACTIVE");return id;}private UUID patient(UUID person){UUID id=UUID.randomUUID();jdbc.update("insert into patient.patient(id,person_id,patient_number) values (?,?,?)",id,person,"PAT-"+id);return id;}private UUID professional(UUID person){UUID id=UUID.randomUUID();jdbc.update("insert into professional.professional(id,person_id,professional_number,professional_type,status) values (?,?,?,?,?)",id,person,"PRO-"+id,"DOCTOR","ACTIVE");return id;}private UUID organization(){UUID id=UUID.randomUUID();jdbc.update("insert into organization.organization(id,organization_number,name) values (?,?,?)",id,"ORG-"+id,"Hospital");return id;}private UUID id(String body){var m=java.util.regex.Pattern.compile("\\\"id\\\":\\\"([^\\\"]+)\\\"").matcher(body);if(!m.find())throw new IllegalArgumentException(body);return UUID.fromString(m.group(1));}record Graph(UUID patient,UUID professional,UUID organization,UUID participant){}
 @TestConfiguration(proxyBeanMethods=false)static class JwtFixtures{@Bean JwtDecoder jwtDecoder(){return token->{Instant now=Instant.now();UUID subject;List<String>roles;switch(token){case"doctor"->{subject=DOCTOR_KEYCLOAK;roles=List.of("DOCTOR");}case"patient"->{subject=PATIENT_KEYCLOAK;roles=List.of("PATIENT");}default->{subject=ADMIN;roles=List.of("PLATFORM_ADMIN");}}return Jwt.withTokenValue(token).header("alg","RS256").subject(subject.toString()).issuer("https://keycloak.example/realms/healthys").audience(List.of("healthys-backend-apps")).issuedAt(now).expiresAt(now.plusSeconds(300)).claim("realm_access",Map.of("roles",roles)).claim("resource_access",Map.of()).build();};}}
}
